window.ScripturaLexicons.BDAG_PART_0225 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-01\" data-source=\"BDAG\" data-search=\"Μαλελεήλ, ὁ nome próprio masculino Maleleel, antepassado de Jesus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαλελεήλ, ὁ</td><td>nome próprio masculino</td><td>Maleleel, antepassado de Jesus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-02\" data-source=\"BDAG\" data-search=\"μαλία remissão ver τρυμαλιά BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαλία</td><td>remissão</td><td>ver τρυμαλιά</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-03\" data-source=\"BDAG\" data-search=\"μάλιστα advérbio superlativo sobretudo; especialmente; certamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάλιστα</td><td>advérbio superlativo</td><td>sobretudo; especialmente; certamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-04\" data-source=\"BDAG\" data-search=\"μᾶλλον advérbio comparativo mais; antes; preferivelmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μᾶλλον</td><td>advérbio comparativo</td><td>mais; antes; preferivelmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-05\" data-source=\"BDAG\" data-search=\"Μάλχος, ου, ὁ nome próprio masculino Malco, servo do sumo sacerdote BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μάλχος, ου, ὁ</td><td>nome próprio masculino</td><td>Malco, servo do sumo sacerdote</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-06\" data-source=\"BDAG\" data-search=\"μάμμη, ης, ἡ substantivo feminino avó BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάμμη, ης, ἡ</td><td>substantivo feminino</td><td>avó</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-07\" data-source=\"BDAG\" data-search=\"μαμωνᾶς, ᾶ, ὁ substantivo masculino riqueza; Mamom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαμωνᾶς, ᾶ, ὁ</td><td>substantivo masculino</td><td>riqueza; Mamom</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-08\" data-source=\"BDAG\" data-search=\"Μαναήν, ὁ nome próprio masculino Manaém, mestre de Antioquia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαναήν, ὁ</td><td>nome próprio masculino</td><td>Manaém, mestre de Antioquia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-09\" data-source=\"BDAG\" data-search=\"Μανάϊμος, ου nome próprio masculino Manaimos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μανάϊμος, ου</td><td>nome próprio masculino</td><td>Manaimos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-10\" data-source=\"BDAG\" data-search=\"Μανασσῆς, ῆ, nome próprio masculino Manassés, filho de José ou rei BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μανασσῆς, ῆ,</td><td>nome próprio masculino</td><td>Manassés, filho de José ou rei</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-11\" data-source=\"BDAG\" data-search=\"μάνδρα, ας, ἡ substantivo feminino aprisco; redil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάνδρα, ας, ἡ</td><td>substantivo feminino</td><td>aprisco; redil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-12\" data-source=\"BDAG\" data-search=\"μανθάνω verbo aprender; vir a conhecer; ouvir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μανθάνω</td><td>verbo</td><td>aprender; vir a conhecer; ouvir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-13\" data-source=\"BDAG\" data-search=\"μανία, ας, ἡ substantivo feminino loucura; frenesi; delírio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μανία, ας, ἡ</td><td>substantivo feminino</td><td>loucura; frenesi; delírio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-14\" data-source=\"BDAG\" data-search=\"μάννα, τό substantivo neutro maná, alimento de Israel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάννα, τό</td><td>substantivo neutro</td><td>maná, alimento de Israel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-15\" data-source=\"BDAG\" data-search=\"μαντεύομαι verbo médio adivinhar; consultar um oráculo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαντεύομαι</td><td>verbo médio</td><td>adivinhar; consultar um oráculo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-16\" data-source=\"BDAG\" data-search=\"μάντις, εως, ὁ substantivo masculino adivinho; vaticinador; profeta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάντις, εως, ὁ</td><td>substantivo masculino</td><td>adivinho; vaticinador; profeta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-17\" data-source=\"BDAG\" data-search=\"Μάξιμος, ου, ὁ nome próprio masculino Máximo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μάξιμος, ου, ὁ</td><td>nome próprio masculino</td><td>Máximo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-18\" data-source=\"BDAG\" data-search=\"μαραίνω verbo murchar; definhar; desaparecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαραίνω</td><td>verbo</td><td>murchar; definhar; desaparecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-19\" data-source=\"BDAG\" data-search=\"μαράνα θά expressão aramaica nosso Senhor, vem! BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαράνα θά</td><td>expressão aramaica</td><td>nosso Senhor, vem!</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0225-20\" data-source=\"BDAG\" data-search=\"μαργαρίτης, ου, ὁ substantivo masculino pérola BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαργαρίτης, ου, ὁ</td><td>substantivo masculino</td><td>pérola</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0225-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαλελεήλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαλελεήλ</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">מַהֲלַלְאֵל</span>; em Jos., Ant. 1, 79; 84, <span class=\"greek\">Μαλάηλος</span>, <span class=\"greek\">ου</span>), Maleleel (Gen 5:12), na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:37</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαλία</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαλία</span>: ver <span class=\"greek\">τρυμαλιά</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάλιστα</h1><div class=\"entry-meta\"><span>advérbio superlativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάλιστα</span> (superlativo do advérbio <span class=\"greek\">μάλα</span>; Hom. e posteriores).</p><p class=\"entry-text\">① Em grau incomum: sobretudo, acima de tudo, especialmente, particularmente, em grau (muito) elevado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:10</a>; 5:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:10</a>; Phlm 16; 1 Cl 13:1; Dg 1; 3:1; IEph 20:2; IPhld ins; MPol 13:1; Hv 1, 1, 8. <span class=\"greek\">καὶ</span> <span class=\"greek\">μ</span>., e acima de tudo, particularmente (Plut., Mor. 835e; Jos., C. Ap. 1, 27; Just., D. 84, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:8</a>; Hv 1, 2, 4. <span class=\"greek\">μ</span>. <span class=\"greek\">δέ</span>, mas especialmente (Il. 1, 16; Lesbonax Gramm. [século II d.C.] p. 8 [ed. RMüller 1900]; TestAbr B 4 p. 109, 6 [Stone p. 66]; Jos., Vi. 14; Just., D. 4, 5; 48, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:10</a>; IPol 3:1; Hm 12, 1, 2; Hs 8, 6, 5; 9, 10, 7. <span class=\"greek\">μ</span>. <span class=\"greek\">γνώστην</span> <span class=\"greek\">ὄντα</span> <span class=\"greek\">σε</span>, visto que conheces extraordinariamente bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:3</a> (cf. Appian, Bell. Civ. 2, 26 §100 <span class=\"greek\">ὁ</span> <span class=\"greek\">μάλιστα</span> <span class=\"greek\">ἐχθρός</span>=“o inimigo mais encarniçado”).</p><p class=\"entry-text\">② Marcador de elevado grau de certeza, em resposta a uma pergunta: certamente, com toda a certeza 1 Cl 43:6 (Just., A II, 2, 18; D. 49, 2 e outros).—DELG s.v. <span class=\"greek\">μάλα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μᾶλλον</h1><div class=\"entry-meta\"><span>advérbio comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μᾶλλον</span> (comparativo do advérbio <span class=\"greek\">μάλα</span>; Hom. e posteriores), “mais, antes”.</p><p class=\"entry-text\">① Em grau maior ou superior: mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:12</a>. <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἔκραζεν</span>, gritava ainda mais alto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:39</a>. <span class=\"greek\">ἔτι</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μᾶλλον</span>, cada vez mais (cf. Diog. L. 9, 10, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:9</a>; Hs 9, 1, 8. <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μᾶλλον</span>, eu o posso fazer ainda mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:4</a>. O segundo termo da comparação é introduzido por <span class=\"greek\">ἤ</span> (Apollon. Paradox. 9; Appian, Iber. 90 §392; Lucian, Adv. Ind. 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:13</a>, ou aparece no genitivo de comparação (X., Mem. 4, 3, 8, Cyr. 3, 3, 45): <span class=\"greek\">πάντων</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">γλώσσαις</span> <span class=\"greek\">λαλῶ</span>, falo (ou posso falar) em línguas mais do que todos vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:18</a> (Just., A I, 12, 1 <span class=\"greek\">πάντων</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἀνθρώπων</span>).—Em emprego absoluto, <span class=\"greek\">μ</span>. pode significar em grau maior (que antes), ainda mais, agora mais do que nunca <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:18</a>; 19:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:14</a>; 22:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:7</a>. Às vezes também é acrescentado a verbos: <span class=\"greek\">Σαῦλος</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐνεδυναμοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:22</a>.—Combinado com adjetivo, substitui o comparativo (Hom. e outros; Just., D. 107, 2 <span class=\"greek\">γενεὰν</span> … <span class=\"greek\">μοιχαλίδα</span> <span class=\"greek\">μ</span>.; Synes., Ep. 123 p. 259d <span class=\"greek\">μ</span>. <span class=\"greek\">ἄξιος</span>): <span class=\"greek\">μακάριόν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μᾶλλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:35</a> (ver 3c abaixo). <span class=\"greek\">καλόν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μᾶλλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:15</a>. <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀναγκαῖά</span> <span class=\"greek\">ἐστιν</span>, são ainda mais necessários <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:22</a>. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τέκνα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐρήμου</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐχούσης</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἄνδρα</span>, os filhos da mulher abandonada são mais numerosos, em grau superior aos da mulher que tem marido = os filhos são mais numerosos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:27</a> (Is 54:1).—Pleonasticamente com palavras e expressões que já contêm a ideia de “mais” (Kühner-G. I 26; OSchwab, Histor. Syntax der griech. Komparation III 1895, 59ss.; B-D-F §246; Rob. 278): <span class=\"greek\">μ</span>. <span class=\"greek\">διαφέρειν</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:24</a>. <span class=\"greek\">περισσεύειν</span> <span class=\"greek\">μᾶλλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:1</a>, 10; com comparativo (trágicos; Hdt. 1, 32; X., Cyr. 2, 2, 12; Dio Chrys. 23 [40], 17; 32 [49], 14; Lucian, Gall. 13; Ps.-Lucian, Charid. 6; Just., A I, 19, 1 e D. 121, 2; Synes., Ep. 79 p. 227c; 103 p. 241d): <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">κρεῖσσον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:23</a>. <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">περισσότερον</span> <span class=\"greek\">ἐκήρυσσον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:36</a>. <span class=\"greek\">περισσοτέρως</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἐχάρημεν</span>, regozijamo-nos ainda mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:13</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐνδοξότεροι</span> Hs 9, 28, 4. <span class=\"greek\">ὅσῳ</span> <span class=\"greek\">δοκεῖ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">μείζων</span> <span class=\"greek\">εἶναι</span>, quanto maior parece ser 1 Cl 48:6b.</p><p class=\"entry-text\">② Por razão ainda mais forte: antes, tanto mais.</p><p class=\"entry-text\">ⓐ Antes, de preferência (ApcMos 31 <span class=\"greek\">ἀνάστα</span> <span class=\"greek\">μ</span>., <span class=\"greek\">εὖξαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>): <span class=\"greek\">μ</span>. <span class=\"greek\">χρῆσαι</span> (X., Mem. 1, 2, 24), antes aproveita-te disso (isto é, da liberdade ou da escravidão) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:21</a> (bibliografia em <span class=\"greek\">χράομαι</span> 1a). Os escravos que possuem senhores cristãos <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">δουλευέτωσαν</span>, devem servi-los ainda melhor (assim REB, NRSV) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:2</a>. <span class=\"greek\">νῦν</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀπουσίᾳ</span> <span class=\"greek\">μου</span>, agora muito mais na minha ausência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:12</a>. <span class=\"greek\">οὐ</span> <span class=\"greek\">πολὺ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὑποταγησόμεθα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πατρί</span>;, não devemos, com muito maior razão, submeter-nos ao Pai? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9</a>. <span class=\"greek\">τοσούτῳ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὅσῳ</span>, tanto mais, visto que 10:25.</p><p class=\"entry-text\">ⓑ Com maior certeza, mais seguramente: <span class=\"greek\">πόσῳ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">σοί</span>, quanto mais certamente a ti Phlm 16. <span class=\"greek\">πόσῳ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὑμᾶς</span> … <span class=\"greek\">ἐξεγείρει</span>, quanto mais certamente vos ressuscitará (presente empregado de maneira vívida) AcPlCor 2:31. <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:9</a> (ver HMüller, Der rabb. Qal-Wachomer Schluss. in paul. Theol., ZNW 58, ’67, 73–92). Muito frequentemente precedido por oração condicional (<span class=\"greek\">εἰ</span>) (Epicurus em Diog. L. 10, 91 <span class=\"greek\">εἰ</span> <span class=\"greek\">γὰρ</span> … , <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἄν</span>=“se … , quanto mais seguramente”): <span class=\"greek\">εἰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χόρτον</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἀμφιέννυσιν</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὑμᾶς</span>;, se Deus assim veste a erva, não vestirá muito mais certamente a vós? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:30</a>. Igualmente <span class=\"greek\">εἰ</span> … <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:10</a>, 15, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:9</a>, 11; <span class=\"greek\">εἰ</span> … <span class=\"greek\">πόσῳ</span> <span class=\"greek\">μ</span>., se … quanto mais certamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:11</a>; 10:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:13</a>; 12:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:12</a>, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:14</a>. <span class=\"greek\">εἰ</span> … <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">μ</span>.;, se … por que não com maior certeza? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:8</a>. <span class=\"greek\">εἰ</span> … <span class=\"greek\">πολὺ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἡμεῖς</span>, se … então com muito maior certeza nós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:25</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">ἄλλοι</span> … <span class=\"greek\">οὐ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἡμεῖς</span>;, se outros (têm direito), não o temos nós com maior razão? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:12</a> (<span class=\"greek\">μ</span>. pode também significar sobretudo, especialmente, por exemplo Himerius, Or. 40 [Or. 6], 2).—CMaurer, Der Schluss ‘a minore ad majus’ als Element paul. Theol., TLZ 85, ’60, 149–52.</p><p class=\"entry-text\">③ Marcador de uma alternativa a alguma coisa: antes, em vez de alguma coisa.</p><p class=\"entry-text\">ⓐ Após uma negação que:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. é expressa: <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰσέλθητε</span>. <span class=\"greek\">πορεύεσθε</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μ</span>., não entreis; ide antes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:6</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβεῖσθε</span> … <span class=\"greek\">φοβεῖσθε</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μ</span>. v. 28; <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χωλὸν</span> <span class=\"greek\">ἐκτραπῇ</span>, <span class=\"greek\">ἰαθῇ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:13</a>. <span class=\"greek\">μὴ</span> … , <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:28</a>; 5:11. <span class=\"greek\">μὴ</span> ou <span class=\"greek\">οὐ</span> … , <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">μ</span>. (TestBenj 8:3; JosAs 26:2 A [p. 80, 2 Bat.]; ParJer 2:5; Just., A I, 27, 5; Syntipas p. 17, 3; 43, 17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:4</a>; AcPt Ox 849, 20.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. não é expressa, embora facilmente suprida pelo contexto: <span class=\"greek\">πορεύεσθε</span> <span class=\"greek\">μ</span>., (não vos volteis para nós) ide antes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:9</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">Βαραββᾶν</span>, para que libertasse, em vez de Jesus, Barrabás <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:11</a>. <span class=\"greek\">ἥδιστα</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">καυχήσομαι</span>, (não orarei para ser libertado), antes de boa vontade me gloriarei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:9</a>. <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">παρακαλῶ</span>, (não ordeno), antes peço Phlm 9; <span class=\"greek\">τοὐναντίον</span> <span class=\"greek\">μ</span>., ao contrário, antes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:7</a>. <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">αἰσχυνθῶμεν</span>, devemos antes envergonhar-nos de nós mesmos (em vez de desconfiar de Maria Madalena) GMary Ox 463, 25.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">μᾶλλον</span>, não antes, após uma afirmação positiva: <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">πεφυσιωμένοι</span> <span class=\"greek\">ἐστέ</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἐπενθήσατε</span>;, estais ensoberbecidos; não deveríeis antes entristecer-vos? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:2</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀδικεῖσθε</span>;, por que não preferis sofrer injustiça (em vez de cometê-la contra os outros)? 6:7a; cf. 7b.</p><p class=\"entry-text\">ⓒ <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἤ</span>(<span class=\"greek\">περ</span>) geralmente (exceções: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:35</a> [Unknown Sayings, 77–81: não constitui exceção e significa “dar é bem-aventurado, não receber”]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:15</a> [mas ver <span class=\"greek\">ἦ</span>]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:27</a>) exclui da consideração o conteúdo da expressão introduzida por <span class=\"greek\">ἤ</span> (Tat. 13, 3 <span class=\"greek\">θεομάχοι</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἤπερ</span> <span class=\"greek\">θεοσεβεῖς</span>; Appian, Iber. 26 §101 <span class=\"greek\">θαρρεῖν</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πλήθει</span> <span class=\"greek\">στρατοῦ</span>=“depositar confiança em Deus, não em …”): <span class=\"greek\">ἠγάπησαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">σκότος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span>, os homens não amaram a luz, mas as trevas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:19</a>; cf. 12:43. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἢ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, não obedecer a Deus, mas antes a vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:19</a>; cf. 5:29.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:4</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ναυκλήρῳ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐπείθετο</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">Παύλου</span> <span class=\"greek\">λεγομένοις</span>, não dava atenção ao que Paulo dizia, mas ao capitão do navio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:11</a>. Igualmente <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἑλόμενος</span> <span class=\"greek\">ἤ</span>, preferiu uma coisa à outra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:25</a>.</p><p class=\"entry-text\">ⓓ <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">δέ</span>, mas antes, ou antes, ou simplesmente antes, introduz uma expressão ou pensamento que complementa e, assim, corrige o que precedeu (Aristoph., Plut. 634; X., Cyr. 5, 4, 49; Demosth. 18, 65; Philo, Aet. M. 23; Just., D. 27, 4; 29, 2; Ath. 17, 3 <span class=\"greek\">μ</span>. <span class=\"greek\">δέ</span>; cf. Ar.; Just., A I, 17, 4 e D. 79, 1 <span class=\"greek\">μ</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">καί</span>): <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀποθανών</span>, <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐγερθείς</span>, Cristo Jesus, que morreu, sim, antes, que ressuscitou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:34</a>. <span class=\"greek\">γνόντες</span> <span class=\"greek\">θεόν</span>, <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">γνωσθέντες</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span>, uma vez que conhecestes a Deus, ou antes, fostes conhecidos por Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:1</a>, 5.—Rydbeck 80ss. DELG s.v. <span class=\"greek\">μάλα</span>. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μάλχος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μάλχος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Porphyr., Pyth. Vi. ins <span class=\"greek\">Πορφύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καὶ</span> M. [de Tiro] e Porphyr., Vi. Plot. 17 p. 111, 3ss. Westerm.; índice de Joseph., quase inteiramente referente a gentios, na realidade árabes nabateus; OGI 640, 3 [Palmira]; inscrição em RDussaud, Mission dans les régions désertiques de la Syrie moyenne 1902, p. 644 n.º 9; inscrições de Haurã: RB 41, ’32, p. 403 n.º 12; p. 578 n.os 130; 131; PBrem 5, 3 [117/19 d.C.]; 6, 3; HWuthnow, E. palmyren. Büste: ELittmann Festschr. ’35, 63–69.—Zahn, comentário ao lugar [com bibliografia]) Malco, escravo do sumo sacerdote, ferido por Pedro durante a prisão de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:10</a>.—BHHW II 1130. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάμμη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάμμη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (originalmente “mãe”; mais tarde) avó (assim Menand., Sam. 28; Herodas 3, 34; 38; Plut., Mor. 704b e outros; SIG 844b, 5; POxy 1644, 12 [63/62 a.C.]; PRein 49, 14; BGU 19 II, 7 e outros; 4 Macc 16:9; Philo, Spec. Leg. 3, 14; Jos., Ant. 10, 237.—Lob. sobre Phryn. 133–35) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:5</a> (<span class=\"greek\">μάμμη</span> e <span class=\"greek\">μήτηρ</span> citadas juntas nominalmente como em Plut., Agis 4, 1.—Cf. também a influência da avó Macrina e da mãe Emélia sobre a vida religiosa do padre da Igreja Basílio, do século IV, quando este crescia [Basilius, Ep. 223, 3 <span class=\"greek\">ἐκ</span> <span class=\"greek\">παιδὸς</span> <span class=\"greek\">ἔλαβον</span> <span class=\"greek\">ἔννοιαν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μακαρίας</span> <span class=\"greek\">μητρός</span> <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μάμμης</span> <span class=\"greek\">Μακρίνης</span>]).—B. 109. DELG s.v. <span class=\"greek\">μάμμη</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαμωνᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαμωνᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (aram. <span class=\"hebrew\" dir=\"rtl\">מָמוֹן</span>, estado enfático <span class=\"hebrew\" dir=\"rtl\">מָמוֹנָא</span>), riqueza, bens, propriedade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:9</a>, 11 (SColella: ZNW 64, ’73, 124–26). Personificado, “Mamom” <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:13</a>; 2 Cl 6:1.—EbNestle, EncBibl 2912ss.; ali (2914s.) também se examina detidamente a etimologia do vocábulo. Ver ainda EKautzsch, Gramm. des Bibl.-Aram. 1884, 10; Dalman, Gramm.2 170s., RE3 XII 1903, 153s.; HZimmern, Akkadische Fremdwörter2 1917, 20; ERiggenbach, ASchlatter Festschr. 1922, 21ss.; MBlack, An Aramaic Approach, 102.—A palavra também se encontra na Mishnah Aboth 2, 17 e no Documento de Damasco p. 14, 20 Schechter 1910=LRost (Kl. T. 167) ’33, p. 26, que não pode ser datado com certeza (ver Bousset, Rel. 15s.); EMeyer, ABA 1919, 9, Abhdlg. p. 50; HRüger: ZNW 64, ’73, 127–31 (empréstimo cananeu cujo sentido original seria “alimento, sustento, provisões”, da raiz <span class=\"hebrew\" dir=\"rtl\">מון</span>).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαναήν, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαναήν</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">מְנַחֵם</span>; 4 Km 15:14 <span class=\"greek\">Μαναήμ</span>; Jos., Ant. 9, 229; 232 <span class=\"greek\">Μανάημος</span>, <span class=\"greek\">ου</span> [15, 374]. Outros judeus com esse nome constam do índice de Schürer), Manaém, um dos profetas e mestres da comunidade de Antioquia, descrito como <span class=\"greek\">Ἡρῴδου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τετραάρχου</span> <span class=\"greek\">σύντροφος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:1</a>.—Sobre o nome, TNöldeke, Beiträge z. semit. Sprachwissensch. 1904, 99; Haenchen, comentário ao lugar; BHHW II 1136.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μανάϊμος, ου</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μανάϊμος</span>, <span class=\"greek\">ου</span> (<span class=\"greek\">Μανάημος</span> em Joseph.), Manaimos, nome de um homem cristão: <span class=\"greek\">τὴν</span> <span class=\"greek\">μητέρα</span> <span class=\"greek\">Μαναϊμου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ἀναστᾶσαν</span> Papias (11:2); cf. <span class=\"greek\">Μαναήν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μανασσῆς, ῆ,</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μανασσῆς</span>, <span class=\"greek\">ῆ</span>, acusativo <span class=\"greek\">ῆ</span> (-<span class=\"greek\">ῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:10</a>, variante textual; Demetr.: 722 Fgm. 1, 12 Jac.; <span class=\"hebrew\" dir=\"rtl\">מְנַשֶּׁה</span>), Manassés (nome predominantemente judaico; entretanto, uma inscrição cipriota [OHoffmann, D. griech. Dialekte I 1891 p. 75 n.º 140] o apresenta também como nome de um greco-romano. Ver <span class=\"greek\">ἀββᾶ</span>, final).</p><p class=\"entry-text\">① Filho primogênito de José (Gen 41:51; JosAs 21:8; Philo, Joseph.), progenitor de uma tribo 13:5 (cf. Gen 48:14). Da tribo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:6</a>.</p><p class=\"entry-text\">② Filho de Ezequias, rei hebreu (4 Km 21:1ss.; 2 Ch 33:1ss.; AscIs; Joseph.); na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:23</a>ss. D.—BHHW II 1136s. (bibliografia).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάνδρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάνδρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (etimologia incerta; Soph. e posteriores; papiros, LXX), aprisco, redil 16:5 (citação de origem incerta; cf. En 89:56; 66s.).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μανθάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μανθάνω</span>, futuro <span class=\"greek\">μαθήσομαι</span> LXX; 2º aoristo <span class=\"greek\">ἔμαθον</span>; imperativo plural <span class=\"greek\">μάθετε</span>, particípio <span class=\"greek\">μαθών</span>; perfeito 3ª pessoa do singular <span class=\"greek\">μεμάθηκεν</span> Jer 9:4, particípio plural <span class=\"greek\">μεμαθηκότες</span> Jer 13:23; infinitivo <span class=\"greek\">μεμαθηκέναι</span> Ps 118:7 (Hom. e posteriores).</p><p class=\"entry-text\">① Adquirir conhecimento ou habilidade mediante instrução, aprender, em emprego absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:7</a>. <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, aprender de alguém como mestre (X., Cyr. 2, 2, 6; Appian, Iber. 23 §89 <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μ</span>.; Sextus 353 <span class=\"greek\">μ</span>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span>; Philo, Deus Imm. 4; Just., D. 32, 5; 78, 1; Ath. 7:2) v. 14b; ser discípulo (<span class=\"greek\">μαθητής</span>) de alguém EpilMosq 2. <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, de alguém (Theognis 1, 28s.: Teógnis ensina o que “eu próprio, quando <span class=\"greek\">παῖς</span> <span class=\"greek\">ἔμαθον</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγαθῶν</span>”; 1, 35; Jos., Ant. 8, 317) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:7</a>. Com acusativo da coisa aprendida, <span class=\"greek\">τὶ</span>, alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:35</a>. <span class=\"greek\">ταῦτα</span> AcPl Ha 1, 26. <span class=\"greek\">πάντα</span> Hs 9, 1, 3, variante textual. Um ensinamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:17</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">θεοσέβειαν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστιανῶν</span> Dg 1; cf. 11:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">δικαιώματα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίου</span>, as ordenanças do Senhor 21:1. <span class=\"greek\">τὸν</span> <span class=\"greek\">Χριστόν</span>=ensinamento cristão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:20</a> (Chion, Ep. 16, 8 <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἔμαθες</span>=aprendeste a conhecer Deus; Tat. 2:2 <span class=\"greek\">ἕνα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀπλανῆ</span> <span class=\"greek\">δεσπότην</span> <span class=\"greek\">μεμαθήκαμεν</span>). Com atração do relativo: <span class=\"greek\">μένε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span> (=<span class=\"greek\">ἐν</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">ἃ</span>) <span class=\"greek\">ἔμαθες</span>, permanece naquilo que aprendeste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:14a</a>. Com objeto suprido pelo contexto (<span class=\"greek\">γράμματα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:15</a> (Goodsp., Probs. 102–4). <span class=\"greek\">μ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, aprender alguma coisa de alguém 9:9. <span class=\"greek\">μ</span>. <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span>, receber instrução acerca de todas as coisas v. 7 (<span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> como em Philo, Spec. Leg. 1, 42; Just., D. 87, 1; Ath. 7, 2). <span class=\"greek\">μ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, aprender alguma coisa do exemplo de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6</a> (B-D-F §220, 2; Rob. 587).—<span class=\"greek\">μ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, aprender alguma coisa de algo: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">συκῆς</span> <span class=\"greek\">μάθετε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">παραβολήν</span>, aprendei da figueira a parábola <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:28</a>.—Com <span class=\"greek\">ὅτι</span> seguinte (Philo, Leg. All. 3, 51) 9:8. Com infinitivo seguinte (Aristoxenus, Fgm. 96 <span class=\"greek\">αὐλεῖν</span>) 1 Cl 8:4 (Is 1:17); 57:2. Com interrogativa indireta seguinte (Just., A I, 40, 5 e D. 32, 2 e outros; Mel., P. 46, 328) 1 Cl 21:8. <span class=\"greek\">τί</span> <span class=\"greek\">ἐστιν</span>, o que isto significa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:13</a>. Com a pergunta precedente (Just., A I, 56, 1) B 5:5; 6:9; 14:4; 16:2, 7; Dg 4:6. Usado com outros verbos: <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μ</span>. (Pla., Ap. 33b, 7, Ep. 344d; Theocr. 5, 39; Ael. Aristid. 45 p. 33 D. p. 40; cf. Polyb. 3, 32, 9 <span class=\"greek\">ὅσῳ</span> <span class=\"greek\">διαφέρει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μαθεῖν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">ἀκούειν</span>, <span class=\"greek\">τοσούτῳ</span> … ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:45</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">παραλαμβάνειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:9</a>. <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἐδύνατο</span> <span class=\"greek\">μαθεῖν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ᾠδήν</span>, ninguém era capaz de aprender o cântico (assim, por exemplo, Bousset; Allo; REB; NRSV) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:3</a>; outros preferem o sentido relacionado entender (como em Lysias 10, 15; Pla., Meno 84d, Tht. 174b, Euthyd. 277e); para o sentido ouvir, ver 4 abaixo.</p><p class=\"entry-text\">② Familiarizar-se com alguma coisa, vir a conhecê-la, aprender.</p><p class=\"entry-text\">ⓐ Aprender a respeito de, vir a conhecer: <span class=\"greek\">τὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστιανισμοῦ</span> <span class=\"greek\">λόγον</span>, o ensinamento cristão MPol 10:1. <span class=\"greek\">τὶ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, alguma coisa de alguém (Sir 8:8s.; EpArist 198; Philo, Fuga 8, Leg. All. 3, 194; Jos., Vi. 62; Just., D. 2, 2; 78, 10; Tat. 36, 2) Dg 4:1; Papias (2:3). Tomar conhecimento de <span class=\"greek\">τὶ</span>, alguma coisa MPol 20:1.</p><p class=\"entry-text\">ⓑ Descobrir, averiguar (trágicos, X.; PRyl 77, 42; POxy 1067, 6; 1671, 20; LXX). <span class=\"greek\">τὶ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, descobrir alguma coisa de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:2</a>. Com <span class=\"greek\">ὅτι</span> seguinte (Arrian, Anab. 2, 5, 7; Esth 1:1n; Jos., Ant. 12, 208) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:27</a>. Em emprego absoluto 16:8.</p><p class=\"entry-text\">③ Chegar a compreender ou realizar alguma coisa, implicando aquisição mais por experiência ou exercício do que por instrução, aprender, assimilar: <span class=\"greek\">ἔμαθεν</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὧν</span> <span class=\"greek\">ἔπαθεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑπακοήν</span>, aprendeu a obediência por meio das coisas que sofreu = realizou a obediência mediante o sofrimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:8</a> (quanto à assonância, cf. Aeschyl., Agam. 177 <span class=\"greek\">τῷ</span> <span class=\"greek\">πάθει</span> <span class=\"greek\">μάθος</span>; Hdt. 1, 207, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">δέ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">παθήματα</span> … <span class=\"greek\">μαθήματα</span>; escólio a Pla. 222b <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πάθῃς</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μάθῃς</span>; Philo, Fuga 138 <span class=\"greek\">ἔμαθον</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">ἔπαθον</span>. Outros exemplos em HWindisch, comentário ao lugar, e CSpicq, RB 56, ’49, 551.—Jogo de palavras semelhante em Theognis 369s. <span class=\"greek\">μωμεῖσθαι</span> … <span class=\"greek\">μιμεῖσθαι</span>=[eles podem] censurar [a mim, mas não] fazer como eu faço).—Com infinitivo seguinte (X., Cyr. 1, 6, 6; Lucian, Dial. Deor. 14, 2; Dt 14:23; Is 2:4; Just., D 15, 1; Ath. 1, 4): <span class=\"greek\">τ</span>. <span class=\"greek\">ἴδιον</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">εὐσεβεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:4</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:14</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">Χριστιανισμὸν</span> <span class=\"greek\">ζῆν</span> IMg 10:1, cf. IRo 4:3. <span class=\"greek\">ἔμαθον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">αὐτάρκης</span> <span class=\"greek\">εἶναι</span>, aprendi a estar contente em qualquer situação em que me encontre (ver <span class=\"greek\">αὐτάρκης</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:11</a>. <span class=\"greek\">ἀργαὶ</span> <span class=\"greek\">μανθάνουσιν</span> <span class=\"greek\">περιερχόμεναι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">οἰκίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:13</a> apresenta muitas dificuldades do ponto de vista linguístico. Talvez se deva inserir <span class=\"greek\">εἶναι</span> ou <span class=\"greek\">ζῆν</span> depois de <span class=\"greek\">ἀργαί</span> (X., An. 3, 2, 25 <span class=\"greek\">ἂν</span> <span class=\"greek\">ἅπαξ</span> <span class=\"greek\">μάθωμεν</span> <span class=\"greek\">ἀργοὶ</span> <span class=\"greek\">ζῆν</span>; assim B-D-F §416, 2; Mlt. 229; Dibelius, Hdb./Hermeneia, comentário ao lugar). Outros substituem por conjectura <span class=\"greek\">λανθάνουσιν</span> (por exemplo, PSchmiedel, ThBl 1, 1922, 222, Zürcher Bibelübers. ’31, apêndice ao NT, nota 12).</p><p class=\"entry-text\">④ Ouvir: <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἐδύνατο</span> <span class=\"greek\">μαθεῖν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ᾠδήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:3</a>, segundo alguns, significa ninguém podia ouvir o cântico (Boll 18ss.; Lohmeyer; Behm). Mas ver o final de 1.—B. 1222. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μανία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μανία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Pind. e outros; papiros, LXX, Philo; Jos., Bell. 1, 506, Ant. 2, 330; apolog. exc. Mel.), loucura, frenesi, delírio. Frequentemente em sentido não diagnóstico, designando comportamento excêntrico ou bizarro em palavra ou ação (cf. a passagem [século II a.C.] de papiro inédito de Tebtúnis em M-M s.v. <span class=\"greek\">φαίνῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μανίαν</span> <span class=\"greek\">ἐμπεπτωκέναι</span>, <span class=\"greek\">διὸ</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">σαυτοῦ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ποιεῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑπομεμένηκας</span>=“pareces ter perdido a razão, pois demonstras pouco respeito por ti mesmo e teu comportamento é muito estranho”. Assim, Sólon é censurado por seus oponentes como portador de <span class=\"greek\">μανία</span>: Solon 9, 1 D.3; ver <span class=\"greek\">μαίνομαι</span>): <span class=\"greek\">τὰ</span> <span class=\"greek\">πολλά</span> <span class=\"greek\">σε</span> <span class=\"greek\">γράμματα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μανίαν</span> <span class=\"greek\">περιτρέπει</span>, o excesso de estudo está te levando à loucura (isto é, tornando-te fanático) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:24</a>.—DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάννα, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάννα</span>, <span class=\"greek\">τό</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">מָן</span>. A forma grega <span class=\"greek\">μάννα</span> [LXX—somente em Ex 16 aparece <span class=\"greek\">μάν</span>; GrBar 6:11; Philo, Leg. Alleg. 2, 84, Det. Pot. Insid. 118; Jos., Ant. 3, 32; Just.] provavelmente se explica pela influência da palavra grega <span class=\"greek\">ἡ</span> <span class=\"greek\">μάννα</span>=“pequeno grão, grânulo” [Hippocr. e outros; POxy 1088, 21; PGM 4, 1874]. Flexão feminina também em Jos., Ant. 3, 296; 5, 21; SibOr 7, 149), “maná”, frequentemente identificado com a exsudação adocicada da tamargueira-do-maná e de árvores afins, produzida pela picada de um inseto; seca e cai sob a forma de grãos pequenos. Ver AKaiser, Der heutige Stand der Mannafrage: Mitteilungen d. Thurgauischen Naturforsch. Gesellschaft, Heft 25, 1924, Wanderungen u. Wandlungen in d. Sinaiwüste 1886–1927: ibid. 1928, 21ss.; HDarlington, Open Court 42, 1928, 372–81; FBodenheimer and OTheodor, Ergebnisse d. Sinai-Exped. 1927 der hebr. Univers. Jerus. 1930; BMalina, The Palestinian Manna Tradition, ’68.</p><p class=\"entry-text\">① Alimento especialmente associado à experiência de Israel, maná.</p><p class=\"entry-text\">ⓐ Fornecido aos israelitas durante suas peregrinações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:31</a>, 49.</p><p class=\"entry-text\">ⓑ Guardado, segundo Ex 16:32ss., no tabernáculo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:4</a>.</p><p class=\"entry-text\">ⓒ Na imagem do mel comido por João Batista: <span class=\"greek\">οὗ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γεῦσις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μ</span>., cujo sabor era como o maná GEb 13, 79.</p><p class=\"entry-text\">② Alimento celestial, relacionado pelo nome ao precedente, maná: <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κεκρυμμένον</span>, o maná escondido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:17</a>.—W-S. 10a 2 p. 92; BHHW II 1141ss.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαντεύομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαντεύομαι</span> (ver o verbete seguinte; Hom. e outros; inscrições, LXX, Philo, Joseph.), depoente médio; aoristo: imperativo 2ª pessoa do singular <span class=\"greek\">μάντευσαι</span> 1 Km 28:8; infinitivo <span class=\"greek\">μαντεύσασθαι</span> Ez 21:26; também com sentido passivo em formas passivas; em nossa literatura, como na LXX, sempre em contexto crítico de quem o pratica.</p><p class=\"entry-text\">① Praticar adivinhação, profetizar, adivinhar, proferir um oráculo (Hom. e outros; 1 Km 28:8=Jos., Ant. 6, 330; SibOr 4, 3; Ar., Tat., Ath., Iren.; Orig., C. Cels. 7, 4, 15 [da Pítia]; Hippol., Ref. 4, 13, 2); de uma adivinha possuída por um espírito ventríloquo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:16</a>.</p><p class=\"entry-text\">② Consultar um adivinho, consultar um oráculo (Pind. e outros; Artem. 3, 20; Jos., C. Ap. 1, 306); acerca de cristãos hesitantes Hm 11:4.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάντις, εως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάντις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ὁ</span> (Hom. e outros; inscrições, LXX, Philo; Jos., Bell. 1, 80, C. Ap. 1, 257 e outros; Ath. 21, 5; Theoph. Ant. 3, 17 [p. 283, 6] com <span class=\"greek\">προγνώστης</span>), pessoa que pratica adivinhação, adivinho, vaticinador, profeta; de profetas cristãos dissidentes aos quais recorrem crentes de fé pouco fundamentada, como a adivinhos Hm 11:2.—DELG. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μάξιμος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μάξιμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, nome frequente (Polyb. 3, 87, 6 e outros; inscrições, papiros, Joseph.), Máximo, nome de um cristão Hv 2, 3, 4.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαραίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαραίνω</span>, aoristo: particípio 3ª pessoa do plural <span class=\"greek\">ἐμάραναν</span> Wsd 19:21, optativo 3ª pessoa do singular <span class=\"greek\">μαράναι</span> Job 15:30. Passivo: 1º futuro <span class=\"greek\">μαρανθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐμαράνθην</span>; particípio perfeito <span class=\"greek\">μεμαραμμένος</span> (B-D-F §72) (Hom. e outros; inscrições, papiros, LXX; geralmente “extinguir, destruir”); em nossa literatura somente passivo com sentido ativo: desaparecer gradualmente, extinguir-se, perder o viço, desaparecer, murchar, a respeito de plantas (escólio a Nicander, Ther. 677; Job 15:30; Wsd 2:8): <span class=\"greek\">ὡς</span> <span class=\"greek\">μεμαραμμέναι</span>, como se estivessem murchas Hs 9, 1, 7; cf. 9, 23, 1s. Do espírito de alguém v 3, 11, 2 (cf. Appian, Bell. Civ. 5, 90 §379 <span class=\"greek\">μαραίνεσθαι</span> acerca de <span class=\"greek\">πνεῦμα</span>, vento=acalmar-se inteiramente, cessar; Jos., Ant. 11, 56; ApcSed 7:6, acerca da beleza). Do nome de Maria: <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μαρανθήσεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> GJs 6:3 (códices, não Bodmer). De pessoas (Aristaen., Ep. 1, 10 <span class=\"greek\">μαραινόμενος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νοῦν</span>), em máxima: <span class=\"greek\">ὁ</span> <span class=\"greek\">πλούσιος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">πορείαις</span> … <span class=\"greek\">μαρανθήσεται</span>, uma pessoa rica murchará no decorrer de seus negócios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:11</a> (ver inscrição sepulcral Sb 5199, 2 <span class=\"greek\">ἐμαράνθη</span>; Jos., Bell. 6, 274 <span class=\"greek\">λιμῷ</span> <span class=\"greek\">μαραινόμενοι</span>; TestSim 3:3).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:34</a>, variante textual (ambas no lugar de <span class=\"greek\">μωρανθῇ</span>).—BHHW II 1144. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαράνα θά</h1><div class=\"entry-meta\"><span>expressão aramaica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαράνα</span> <span class=\"greek\">θά</span>=<span class=\"hebrew\" dir=\"rtl\">מָרַנָא</span> <span class=\"hebrew\" dir=\"rtl\">תָא</span>, (nosso) Senhor, vem! (<span class=\"greek\">μαρὰν</span> <span class=\"greek\">ἀθά</span> [alguns manuscritos e edições] representa <span class=\"hebrew\" dir=\"rtl\">מָרַן</span> <span class=\"hebrew\" dir=\"rtl\">אֲתָא</span>, “[nosso] Senhor veio”); fórmula aramaica que D 10:6 associa ao que parece ser a primitiva liturgia cristã da Ceia do Senhor. Usada por Paulo sem explicação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:22</a>. (Sobre D 10:6, ver JEmerton, Maranatha and Ephphatha, JTS 18, ’67, 427–31 e Moule abaixo. Sobre ambas as passagens, P-ÉLangevin, Jésus Seigneur, ’67, 168–208; 236–98.)—EKautzsch, Gramm. d. Bibl.-Aram. 1884, 12; 174, StKr. 74, 1901, 296; EbNestle, Theol. Studien aus Württemb. 5, 1884, 186ss.; TNöldeke, GGA 1884, 1023; Dalman, Gramm.2 152, 3; 357, 1, Worte 269; FSchulthess, D. Problem d. Sprache Jesu 1917, p. 28, 50; Dssm., D. Urgeschichte d. Christentums im Lichte der Sprachforschung 1910, 26ss.; Zahn, Einl. I3 216s.; WBousset, Jesus der Herr 1916, 22ss.; EHommel, ZNW 15, 1914, 317–22ss. (<span class=\"hebrew\" dir=\"rtl\">מָרַן</span> <span class=\"hebrew\" dir=\"rtl\">אָתָא</span>=“nosso Senhor é o sinal”=“o <span class=\"hebrew\" dir=\"rtl\">א</span> e o <span class=\"hebrew\" dir=\"rtl\">ת</span>”. Assim, anteriormente, CBruston, Rev. de Théol. et des Quest. Rel. 22, 1913, 402–8); FDölger, Sol Salutis 1920, 153ss.; CFabricius, Urbekenntnisse d. Christenheit: RSeeberg Festschr. 1929 I 21–41; Field, Notes, 180; HCadbury, JBL 58, ’39, p. x; Goodsp., Probs. 166–68; CMoule, NTS 6, ’60, 307–10; SSchulz, ZNW 53, ’62, 125–44; JFitzmyer, To Advance the Gospel ’81, 218–35.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0225-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαργαρίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαργαρίτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Theophr.; Strabo; Aelian, NA 10, 13; papiros; En 18:7; TestJud 13:5; empréstimo no rabínico), pérola.</p><p class=\"entry-text\">ⓐ Com ouro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:9</a>. Com ouro e pedras preciosas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:4</a>; 18:12, 16. Das pérolas que servem de portas à cidade celestial 21:21 (cada porta é uma única pérola: EBurrows, JTS 43, ’42, 177–79). <span class=\"greek\">καλοὶ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:45</a>; <span class=\"greek\">πολύτιμος</span> <span class=\"greek\">μ</span>., uma pérola de grande valor v. 46 (<span class=\"greek\">μ</span>. mais procuradas do que ouro, Chares of Mitylene [século IV a.C.]: 125 Fgm. 3 Jac.; entre os indianos, valiam 3 vezes mais do que ouro puro: Arrian, Ind. 8, 13, e sempre muito procuradas: ibid. 8, 9).</p><p class=\"entry-text\">ⓑ Em linguagem figurada, num provérbio (ver <span class=\"greek\">χοῖρος</span>): <span class=\"greek\">βάλλειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χοίρων</span>, lançar pérolas aos porcos, isto é, confiar alguma coisa preciosa (cf. referências citadas em Betz, SM 499 n. 590; ver também Eur., Bacch. 480; sobre o valor atribuído às pérolas na Antiguidade, ver ainda HUsener, Die Perle: Weizsäcker Festschr. 1892, 203–13) a pessoas que não podem ou não querem apreciá-la <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:6</a> (interpretação diferente em GSchwartz, NovT 14, ’72, 18–25). <span class=\"greek\">πνευματικοὶ</span> <span class=\"greek\">μ</span>., pérolas espirituais, a respeito das cadeias de um mártir IEph 11:2.—HKahane, Traditio 13, ’57, 421–24; RAC 505–52; Kl. Pauly 3, 1020s.; BHHW III 1422s.—DELG. EDNT. TW. Sv.</p></section></article>"};
